// Week 1 questions (built-in). Loaded into the database on first use.
const COURSES = [{"id":"gst","code":"GST111","title":"The Noun: Meaning and Categories","color":"#8a5a3c","timePerQ":30,"questions":[{"q":"A noun is best described as:","opts":["A naming word","An action word","A describing word","A word that replaces a name"],"ans":"A naming word","why":"A noun names a person, animal, place, thing, idea, quality or action."},{"q":"The largest word class in English is the:","opts":["Noun","Verb","Adjective","Adverb"],"ans":"Noun","why":"The lecture states that the noun is the largest word class in English."},{"q":"According to the lecture, nouns can be classified into how many specific categories?","opts":["Six","Four","Eight","Two"],"ans":"Six","why":"The six are proper, concrete, common, abstract, collective and material."},{"q":"Which pair shows the two broad divisions of nouns?","opts":["Countable and uncountable","Proper and common","Concrete and abstract","Singular and collective"],"ans":"Countable and uncountable","why":"Besides the six categories, nouns divide broadly into countable and uncountable."},{"q":"‘Pamela’, ‘lion’, ‘Benin City’ and ‘textbook’ all show that a noun can name a:","opts":["Person, animal, place or thing","Quality only","Feeling only","Action only"],"ans":"Person, animal, place or thing","why":"These are a person, an animal, a place and a thing."},{"q":"‘Explosion’ is an example of a noun that names an:","opts":["Action","Animal","Place","Person"],"ans":"Action","why":"Nouns can sometimes name ideas (honesty), qualities (beauty) or actions (explosion)."},{"q":"A proper noun refers to:","opts":["A particular person, place or thing","A general class of things","Something that cannot be counted","A group of individuals"],"ans":"A particular person, place or thing","why":"Proper nouns name specific persons, places, organisations or objects."},{"q":"Which of these is a proper noun?","opts":["Miva University","university","student","city"],"ans":"Miva University","why":"Miva University names one particular institution, so it takes a capital letter."},{"q":"Proper nouns always begin with:","opts":["A capital letter","A small letter","A determiner","A numeral"],"ans":"A capital letter","why":"Proper nouns are marked in writing by an initial capital letter."},{"q":"Which sentence shows a proper noun behaving like a common noun?","opts":["I have two Toyotas and a Benz.","Alan is my friend.","London is a big city.","Abuja is the capital."],"ans":"I have two Toyotas and a Benz.","why":"‘two Toyotas’ is plural and takes a number, like a common noun (a product category)."},{"q":"In ‘Have you met our guests, the Emekas?’, ‘the Emekas’ refers to:","opts":["A family whose name is Emeka","A single man named Emeka","A town called Emeka","A company"],"ans":"A family whose name is Emeka","why":"A proper noun can take a determiner and plural when it refers to a family."},{"q":"Which category of proper nouns regularly occurs with a determiner such as ‘the’?","opts":["Plural geographical names like the Bahamas","First names like Sandra","Names of cities like Abuja","Single-word names like Alan"],"ans":"Plural geographical names like the Bahamas","why":"Plural geographical names, public institutions, famous ships and newspapers usually take ‘the’."},{"q":"Which of these normally takes ‘the’ before it?","opts":["the Times (a newspaper)","Sandra","Abuja","London"],"ans":"the Times (a newspaper)","why":"Newspapers and periodicals such as the Times regularly occur with a determiner."},{"q":"A proper noun does NOT normally:","opts":["Take a determiner before it","Begin with a capital letter","Refer to one person or place","Appear as a single-word name"],"ans":"Take a determiner before it","why":"Ordinary proper nouns do not take determiners (‘the Sandra’ is wrong)."},{"q":"Which is the most polite and respectful way to address a woman named Abdullahi?","opts":["Mrs Abdullahi","Abdullahi","Mrs Kemi Abdullahi (spoken to her)","Hey, Abdullahi"],"ans":"Mrs Abdullahi","why":"Use an honorific plus the family name when talking to people."},{"q":"Which form should be avoided when speaking TO a person?","opts":["Mr. Shola Kabiru (first and last name together)","Mr Kabiru","Shola, for friendliness","Dr Kabiru"],"ans":"Mr. Shola Kabiru (first and last name together)","why":"The lecture says not to use both first and last names when addressing someone, though you can when speaking about them."},{"q":"Using only a last name (e.g. ‘Soyinka’) is acceptable when:","opts":["Talking or writing about very well-known people","Addressing your lecturer","Greeting a stranger","Writing to an elder"],"ans":"Talking or writing about very well-known people","why":"Last name alone is neither friendly nor respectful, except for very well-known people."},{"q":"In British English, ‘Mr’, ‘Mrs’ and ‘Dr’ are written:","opts":["Without a full stop","With a full stop","In capitals only","In brackets"],"ans":"Without a full stop","why":"The lecture notes the absence of a punctuation mark at the end of Mr, Mrs, Dr in British English."},{"q":"‘James, are you free this evening?’ is an example of address that is:","opts":["Friendly and casual","Distant and respectful","Rude","Official"],"ans":"Friendly and casual","why":"First name only signals friendliness."},{"q":"‘Mr James, I wonder if you have some time to spare this evening.’ sounds:","opts":["Distant and respectful","Friendly and casual","Angry","Childish"],"ans":"Distant and respectful","why":"An honorific plus name is polite but more distant."},{"q":"In ‘my favourite Auntie Sharon’, ‘Auntie’ begins with a capital letter because:","opts":["It is used as a title","It begins a sentence","It is a collective noun","It is plural"],"ans":"It is used as a title","why":"When a kinship word is used as a title with a name, it is capitalised."},{"q":"A common noun refers to:","opts":["A general type of person, animal or thing","A specific named person","Only places","Only abstract ideas"],"ans":"A general type of person, animal or thing","why":"Common nouns are the opposite of proper nouns."},{"q":"Which of these is a common noun?","opts":["market","Lagos","Daniel","Drumbeat"],"ans":"market","why":"‘market’ names a class of things, not one specific place."},{"q":"A common noun is written in small letters except when:","opts":["It begins a sentence","It follows ‘the’","It is plural","It names a person"],"ans":"It begins a sentence","why":"Common nouns are only capitalised at the start of a sentence."},{"q":"In ‘I consider Nkechi a good friend’, the common noun is:","opts":["friend","Nkechi","consider","good"],"ans":"friend","why":"‘Nkechi’ is a proper noun; ‘friend’ is a common noun."},{"q":"A concrete noun refers to things that:","opts":["Can be seen or touched","Cannot be seen or touched","Are always plural","Are always names of people"],"ans":"Can be seen or touched","why":"Concrete nouns have a position in time and space."},{"q":"Which of these is a concrete noun?","opts":["desk","honesty","love","peace"],"ans":"desk","why":"A desk can be seen and touched."},{"q":"‘Blood’ and ‘air’ are examples of concrete nouns naming:","opts":["A liquid and a gas","Two feelings","Two qualities","Two groups"],"ans":"A liquid and a gas","why":"The lecture lists liquids (blood) and gases (air) among concrete nouns."},{"q":"A concrete noun can be used with:","opts":["Both definite and indefinite articles","Only the definite article","No articles at all","Only numerals"],"ans":"Both definite and indefinite articles","why":"Examples: the man, a suit, an apple."},{"q":"In ‘He wanted me to give an apple to the woman’, ‘apple’ and ‘woman’ are:","opts":["Concrete nouns","Abstract nouns","Collective nouns","Proper nouns"],"ans":"Concrete nouns","why":"Both can be seen and touched."},{"q":"An abstract noun refers to things that:","opts":["Can neither be seen nor touched","Can be seen","Can be touched","Are always countable"],"ans":"Can neither be seen nor touched","why":"Abstract nouns are the opposite of concrete nouns."},{"q":"Which of these is an abstract noun?","opts":["education","radio","book","tank"],"ans":"education","why":"Education is an idea or concept."},{"q":"Abstract nouns normally refer to:","opts":["Ideas, concepts or feelings","Physical objects","Groups of people","Substances"],"ans":"Ideas, concepts or feelings","why":"Examples: education (idea), love (feeling)."},{"q":"‘Honesty’ and ‘strength’ are abstract nouns of:","opts":["Quality","State of mind","Events","Groups"],"ans":"Quality","why":"They name qualities."},{"q":"‘Emotion’ and ‘peace’ are abstract nouns describing:","opts":["A state of mind","A quality of a person only","A place","A group"],"ans":"A state of mind","why":"The lecture classes them as states of mind."},{"q":"‘Victory’ and ‘examination’ are abstract nouns describing:","opts":["Events and actions","Qualities","Physical things","Families"],"ans":"Events and actions","why":"They name events or actions."},{"q":"Which ending commonly signals an abstract noun?","opts":["-hood (as in manhood)","-ly","-ed","-ful"],"ans":"-hood (as in manhood)","why":"Many abstract nouns end in -ing, -ness, -hood, -ty, -al and -ance."},{"q":"Which of these abstract nouns is uncountable?","opts":["information","event","visit","cause"],"ans":"information","why":"Information, research and accommodation are uncountable abstract nouns."},{"q":"Which of these abstract nouns is countable?","opts":["event","research","accommodation","information"],"ans":"event","why":"Event, visit and cause are countable abstract nouns."},{"q":"A collective noun signifies:","opts":["A group of individuals or objects as one whole","One single person","A substance","A feeling"],"ans":"A group of individuals or objects as one whole","why":"Examples: committee, team, crowd, herd."},{"q":"Which of these is a collective noun?","opts":["committee","lion","honesty","rice"],"ans":"committee","why":"A committee is a group of people treated as one body."},{"q":"Collective nouns behave like:","opts":["Ordinary countable nouns","Proper nouns only","Abstract nouns only","Uncountable nouns only"],"ans":"Ordinary countable nouns","why":"They can be plural and take ‘the’."},{"q":"‘The committee is tired of Management’s attitude.’ uses singular concord because the focus is on:","opts":["The group as a whole","The individual members","The manager","The attitude"],"ans":"The group as a whole","why":"Singular concord is preferred when the group is the focus."},{"q":"‘The committee are tired of Management’s attitude.’ uses a plural verb because the focus is on:","opts":["The individual members","The group as one unit","The building","Management only"],"ans":"The individual members","why":"A plural verb stresses the members of the group."},{"q":"Countable nouns are those that:","opts":["Stand for entities that can be counted","Cannot be counted","Never take plural","Are always abstract"],"ans":"Stand for entities that can be counted","why":"Examples: doctor, car, book, event."},{"q":"What is the main characteristic of countable nouns?","opts":["Number","Gender","Tense","Mood"],"ans":"Number","why":"Countable nouns can be singular or plural."},{"q":"Which of these is uncountable?","opts":["garri","book","stove","chalk"],"ans":"garri","why":"Garri, water, powder, rice, salt and wine are uncountable."},{"q":"Uncountable nouns usually take determiners such as:","opts":["much, little and a lot of","a and an","each and neither","one and two"],"ans":"much, little and a lot of","why":"Uncountable nouns cannot be isolated and counted, so they take quantity words."},{"q":"‘A loaf of’, ‘a cube of’ and ‘a bag of’ are:","opts":["Units of measurement used with uncountable nouns","Determiners for proper nouns","Collective nouns","Plural endings"],"ans":"Units of measurement used with uncountable nouns","why":"They let us measure things that cannot be counted directly."},{"q":"‘Chicken vs chickens’ and ‘contact vs contacts’ show that:","opts":["Some nouns can be both countable and uncountable","All nouns are uncountable","Proper nouns can be plural","Abstract nouns are always concrete"],"ans":"Some nouns can be both countable and uncountable","why":"The same noun may change type depending on meaning."}]},{"id":"phy","code":"PHY101","title":"Units, Displacement, Velocity and Acceleration","color":"#1e5a8c","timePerQ":30,"questions":[{"q":"Units of dimension are divided into which two groups?","opts":["Fundamental and derived units","Metric and imperial units","Scalar and vector units","Basic and advanced units"],"ans":"Fundamental and derived units","why":"The lecture divides them into fundamental (base) and derived units."},{"q":"A fundamental unit is:","opts":["An independent unit used to measure a base quantity","A unit built by combining other units","A unit used only for energy","A unit that always has a direction"],"ans":"An independent unit used to measure a base quantity","why":"A fundamental unit cannot be expressed in terms of other physical quantities."},{"q":"A derived unit is:","opts":["A dependent unit formed by combining SI base units","An independent base unit","A unit with no symbol","A unit used only in chemistry"],"ans":"A dependent unit formed by combining SI base units","why":"Derived units result from mathematical combinations of base units."},{"q":"How many fundamental quantities are listed in the lecture?","opts":["Seven","Three","Five","Ten"],"ans":"Seven","why":"Length, mass, time, electric current, temperature, amount of substance and luminous intensity."},{"q":"The dimension symbol for length is:","opts":["L","M","T","J"],"ans":"L","why":"Length = L, mass = M, time = T."},{"q":"The dimension symbol for mass is:","opts":["M","L","T","N"],"ans":"M","why":"Mass is represented by M."},{"q":"Which fundamental quantity has the dimension symbol A?","opts":["Electric current","Amount of substance","Luminous intensity","Temperature"],"ans":"Electric current","why":"A stands for electric current."},{"q":"Which fundamental quantity has the dimension symbol N?","opts":["Amount of substance","Electric current","Length","Mass"],"ans":"Amount of substance","why":"N stands for amount of substance."},{"q":"Which fundamental quantity has the dimension symbol J?","opts":["Luminous intensity","Temperature","Time","Mass"],"ans":"Luminous intensity","why":"J stands for luminous intensity."},{"q":"Which of these is NOT a fundamental quantity?","opts":["Velocity","Length","Mass","Time"],"ans":"Velocity","why":"Velocity is derived from length and time."},{"q":"The SI unit of velocity is:","opts":["m/s","m/s²","kg/m³","N"],"ans":"m/s","why":"Velocity is displacement divided by time."},{"q":"The unit of velocity is called a derived unit because it:","opts":["Combines the base units of length and time","Is measured in seconds only","Has no direction","Is used only in kilometres"],"ans":"Combines the base units of length and time","why":"m/s is made up of metres and seconds."},{"q":"The SI unit of density is:","opts":["kg/m³","m/s","N","J"],"ans":"kg/m³","why":"Density = mass/volume."},{"q":"Density is defined as:","opts":["Mass per unit volume","Volume per unit mass","Force per unit area","Distance per unit time"],"ans":"Mass per unit volume","why":"Density = mass ÷ volume."},{"q":"The SI-derived unit for volume is the:","opts":["Cubic metre","Square metre","Litre per second","Kilogram"],"ans":"Cubic metre","why":"Volume uses metre cubed."},{"q":"Force is calculated as:","opts":["Mass × acceleration","Mass ÷ acceleration","Velocity × time","Distance ÷ time"],"ans":"Mass × acceleration","why":"Force = mass × acceleration."},{"q":"The SI unit of force is the:","opts":["Newton","Joule","Watt","Pascal"],"ans":"Newton","why":"1 N = 1 kg·m/s²."},{"q":"One newton is equal to:","opts":["1 kg·m/s²","1 kg·m²/s²","1 kg/m³","1 m/s"],"ans":"1 kg·m/s²","why":"Force = kg × m/s²."},{"q":"The SI unit of energy is the:","opts":["Joule","Newton","Metre","Kilogram"],"ans":"Joule","why":"Energy is measured in joules (J)."},{"q":"Energy (work done) is calculated as:","opts":["Force × distance","Mass × velocity","Force ÷ distance","Distance ÷ time"],"ans":"Force × distance","why":"Work done = force × distance."},{"q":"One joule in base units is:","opts":["kg·m²/s²","kg·m/s²","kg/m³","m/s²"],"ans":"kg·m²/s²","why":"Energy = kg m²/s²."},{"q":"The formula for displacement is:","opts":["Δx = xf − xi","Δx = xf + xi","Δx = xi ÷ xf","Δx = xf × xi"],"ans":"Δx = xf − xi","why":"Displacement is final position minus initial position."},{"q":"The SI unit of displacement is the:","opts":["Metre","Kilometre","Mile","Foot"],"ans":"Metre","why":"Other units can be used but must be converted to metres."},{"q":"Displacement is different from distance because it has:","opts":["Direction as well as magnitude","Only magnitude","No unit","No formula"],"ans":"Direction as well as magnitude","why":"Displacement is distance covered in a specified direction."},{"q":"An object moves from x = 2 m to x = 9 m. Its displacement is:","opts":["7 m","11 m","−7 m","18 m"],"ans":"7 m","why":"Δx = 9 − 2 = 7 m."},{"q":"An object moves from x = 10 m to x = 4 m. Its displacement is:","opts":["−6 m","6 m","14 m","−14 m"],"ans":"−6 m","why":"Δx = 4 − 10 = −6 m (towards the negative direction)."},{"q":"Before calculating, a distance given in 5 km should be converted to:","opts":["5000 m","50 m","500 m","0.5 m"],"ans":"5000 m","why":"1 km = 1000 m, and the SI unit is the metre."},{"q":"Speed is the rate of change of:","opts":["Distance","Displacement","Acceleration","Force"],"ans":"Distance","why":"The lecture defines speed as rate of change of distance."},{"q":"Velocity is the rate of change of:","opts":["Displacement","Distance only","Mass","Energy"],"ans":"Displacement","why":"Velocity is speed in a particular direction."},{"q":"A car covers 120 m in 10 s at a constant rate. Its velocity is:","opts":["12 m/s","1200 m/s","0.08 m/s","130 m/s"],"ans":"12 m/s","why":"v = d/t = 120/10 = 12 m/s."},{"q":"A train travels 80 km at 50 km/hr. Using v = d/t, the time taken is:","opts":["1.6 hours","0.6 hours","4 hours","2.5 hours"],"ans":"1.6 hours","why":"t = 80 ÷ 50 = 1.6 hr."},{"q":"A speed of 72 km/h expressed in m/s is:","opts":["20 m/s","72 m/s","259 m/s","2 m/s"],"ans":"20 m/s","why":"72 × 1000 ÷ 3600 = 20 m/s."},{"q":"Acceleration is the rate of change of:","opts":["Velocity","Displacement","Mass","Distance"],"ans":"Velocity","why":"Acceleration measures how fast velocity changes."},{"q":"The SI unit of acceleration is:","opts":["m/s²","m/s","kg·m/s²","m"],"ans":"m/s²","why":"Metres per second squared."},{"q":"According to the lecture, you can accelerate by:","opts":["Changing your speed, your direction, or both","Changing your mass only","Staying at constant velocity","Changing your position only"],"ans":"Changing your speed, your direction, or both","why":"Velocity has speed and direction, so changing either is acceleration."},{"q":"A body goes from 0 to 20 m/s in 5 s. Its average acceleration is:","opts":["4 m/s²","100 m/s²","0.25 m/s²","15 m/s²"],"ans":"4 m/s²","why":"a = (20 − 0)/5 = 4 m/s²."},{"q":"Zero displacement occurs when:","opts":["The final position equals the initial position","The object is moving fast","The object has no mass","The object is falling"],"ans":"The final position equals the initial position","why":"If you return to the starting point, displacement is zero."},{"q":"An object completes one full circle and returns to its start. Its displacement is:","opts":["Zero","Equal to the circumference","Equal to the diameter","Negative"],"ans":"Zero","why":"Final and initial positions are the same."},{"q":"Negative displacement means:","opts":["The object moved in the negative direction","The object did not move","The object moved faster","The object lost mass"],"ans":"The object moved in the negative direction","why":"If positive is to the right, a negative displacement is to the left."},{"q":"Positive displacement occurs when:","opts":["The final position is further in the positive direction than the initial position","The object returns to the start","The object moves left of origin","The object stops"],"ans":"The final position is further in the positive direction than the initial position","why":"The object has moved in the positive direction."},{"q":"Uniform velocity means a body covers:","opts":["Equal distances in equal time intervals","Different distances in equal intervals","Distance with changing direction","No distance"],"ans":"Equal distances in equal time intervals","why":"Both speed and direction stay constant."},{"q":"Variable (non-uniform) velocity means the displacement is:","opts":["Different in equal intervals of time","The same in equal intervals","Always zero","Always negative"],"ans":"Different in equal intervals of time","why":"Variable velocity changes from instant to instant."},{"q":"Average velocity is:","opts":["Total displacement ÷ total time taken","Total mass ÷ time","Final velocity × time","Distance × time"],"ans":"Total displacement ÷ total time taken","why":"Average velocity = Δx/Δt."},{"q":"Instantaneous velocity is the rate of change of displacement:","opts":["At a particular point in time","Over a whole journey","Only when stopped","Only in circles"],"ans":"At a particular point in time","why":"It describes velocity at one instant."},{"q":"Instantaneous speed is:","opts":["The magnitude of the instantaneous velocity","The same as acceleration","Always negative","The total distance"],"ans":"The magnitude of the instantaneous velocity","why":"It has the same value as instantaneous velocity but no direction."},{"q":"Uniform acceleration means velocity increases:","opts":["By equal amounts in equal intervals of time","By random amounts","Only in a circle","Never"],"ans":"By equal amounts in equal intervals of time","why":"The lecture gives free fall as an example."},{"q":"Which of these is an example of uniform acceleration?","opts":["Free falling of an object","A parked car","An object at rest","A body at constant velocity"],"ans":"Free falling of an object","why":"Free fall has constant acceleration."},{"q":"Kinematics is the study of:","opts":["Motion without considering the forces that cause it","Forces that cause motion","Heat and temperature","Light and sound"],"ans":"Motion without considering the forces that cause it","why":"Kinematics describes how things move."},{"q":"Which is an application of displacement mentioned in the lecture?","opts":["A jogger on a jogging track","The falling of an apple","A bat striking a ball","Moon orbiting Earth"],"ans":"A jogger on a jogging track","why":"The lecture lists a jogger, a teacher walking across a blackboard, and a football coach pacing the sideline."},{"q":"Which is an application of acceleration mentioned in the lecture?","opts":["The falling of an apple due to gravity","A teacher walking","A jogger on a track","A passenger walking in a plane"],"ans":"The falling of an apple due to gravity","why":"Gravity accelerates a falling apple."}]},{"id":"sta1","code":"Statistics","title":"Introduction to Statistics and Data","color":"#b3382c","timePerQ":30,"questions":[{"q":"Statistics is a branch of mathematics that deals with:","opts":["Collection, analysis, interpretation, presentation and organisation of data","Only drawing graphs","Only solving equations","Only counting people"],"ans":"Collection, analysis, interpretation, presentation and organisation of data","why":"This is the lecture’s definition."},{"q":"The purpose of Statistics is to:","opts":["Provide methods for understanding and making decisions based on data","Replace data with opinions","Remove the need for sampling","Create new numbers without data"],"ans":"Provide methods for understanding and making decisions based on data","why":"Statistics gives tools for decisions based on data."},{"q":"Statistics finds application in:","opts":["Business, healthcare, social sciences and engineering","Only business","Only engineering","Only mathematics classrooms"],"ans":"Business, healthcare, social sciences and engineering","why":"It is used in many fields."},{"q":"‘Statistics’ (capital S) refers to:","opts":["The branch of mathematics that studies data","A piece of numerical information","A value computed from a sample","A single observation"],"ans":"The branch of mathematics that studies data","why":"Capital S Statistics is the field itself."},{"q":"‘statistics’ (lowercase s) refers to:","opts":["Any piece of numerical information or data analysed by the field","The branch of mathematics","A single calculated value","A graph"],"ans":"Any piece of numerical information or data analysed by the field","why":"Lowercase statistics are the numerical data."},{"q":"A ‘statistic’ refers to:","opts":["A specific value calculated from a set of data","The whole field of study","Any raw information","A type of survey"],"ans":"A specific value calculated from a set of data","why":"For example, the sample mean."},{"q":"Which of these is an example of a statistic?","opts":["The sample mean","A questionnaire","A pie chart","A population"],"ans":"The sample mean","why":"The sample mean is calculated from data."},{"q":"The sample mean is calculated as:","opts":["(1/n) × the sum of the observations","The largest observation","The sum divided by n²","The difference of the first and last values"],"ans":"(1/n) × the sum of the observations","why":"X̄ = (1/n) Σ xi."},{"q":"In the formula for the sample mean, n stands for:","opts":["The sample size","The population size","The mean","The largest value"],"ans":"The sample size","why":"n is the number of observations."},{"q":"In the sample mean formula, the symbol Σ means:","opts":["Summation (adding up)","Multiplication","Subtraction","Division"],"ans":"Summation (adding up)","why":"Σ means sum all the xi."},{"q":"The notation x₁, x₂, …, xₙ represents:","opts":["A sample of n observations","The mean","The branches of statistics","Types of data"],"ans":"A sample of n observations","why":"They are the individual observations."},{"q":"The two branches of statistics are:","opts":["Descriptive and inferential","Primary and secondary","Numerical and categorical","Simple and complex"],"ans":"Descriptive and inferential","why":"Statistics splits into descriptive and inferential."},{"q":"Descriptive statistics is mainly used to:","opts":["Describe and summarise data in a meaningful way","Generalise to a whole population","Predict with probability","Collect secondary data"],"ans":"Describe and summarise data in a meaningful way","why":"They allow simpler interpretation of data."},{"q":"A limitation of descriptive statistics is that it:","opts":["Cannot make conclusions beyond the data analysed","Cannot summarise data","Cannot use numbers","Cannot be shown in graphs"],"ans":"Cannot make conclusions beyond the data analysed","why":"Descriptive statistics only describes the data at hand."},{"q":"Inferential statistics is used to:","opts":["Draw inferences about a population from a sample","Only list the data","Avoid probability","Describe only the sample"],"ans":"Draw inferences about a population from a sample","why":"It generalises from sample to population."},{"q":"Inferential statistics achieves induction within a:","opts":["Probabilistic framework","Descriptive table","Pictorial chart","Fixed formula with no uncertainty"],"ans":"Probabilistic framework","why":"Inference is expressed using probability."},{"q":"Summarising a class’s test scores with an average and a chart is an example of:","opts":["Descriptive statistics","Inferential statistics","Tertiary data","Time series data"],"ans":"Descriptive statistics","why":"It only describes the class data."},{"q":"Using a sample of 200 voters to estimate how all voters will vote is an example of:","opts":["Inferential statistics","Descriptive statistics","Primary data only","Audio data"],"ans":"Inferential statistics","why":"Generalising from sample to population is inference."},{"q":"Which of these is listed as an importance of statistics?","opts":["Valuable decision making","Removing all uncertainty","Avoiding data collection","Replacing planning"],"ans":"Valuable decision making","why":"Other importance: feasibility studies, planning, forecasting, policy formulation."},{"q":"Which of these is NOT listed as an importance of statistics?","opts":["Eliminating the need for data","Effective planning and development","Forecasting future activities and targets","Formulating policies to achieve forecasted activities"],"ans":"Eliminating the need for data","why":"Statistics depends on data, it does not remove the need for it."},{"q":"Data refers to:","opts":["A collection of facts, figures or statistics that can be analysed","Only numbers","Only text","Only graphs"],"ans":"A collection of facts, figures or statistics that can be analysed","why":"Data can be in many formats."},{"q":"Data can take the form of:","opts":["Text, numbers, images, videos or other storable formats","Only numbers","Only images","Only audio"],"ans":"Text, numbers, images, videos or other storable formats","why":"The lecture says any format that can be stored and processed."},{"q":"Which of these is NOT listed as a type of data?","opts":["Chemical data","Numerical data","Spatial data","Audio data"],"ans":"Chemical data","why":"The listed types are numerical, categorical, time series, spatial, audio, image and text."},{"q":"How many types of data are listed by nature in the lecture?","opts":["Seven","Three","Five","Ten"],"ans":"Seven","why":"Numerical, categorical, time series, spatial, audio, image, text."},{"q":"Time series data is data:","opts":["Recorded over successive points in time","Recorded at one instant only","Made of images only","That has no numbers"],"ans":"Recorded over successive points in time","why":"Time series observations are ordered in time (e.g. monthly sales)."},{"q":"Spatial data is data that:","opts":["Is linked to geographic location","Has no location","Is only audio","Is only text"],"ans":"Is linked to geographic location","why":"Examples: map coordinates, regional data."},{"q":"Blood group and gender are examples of:","opts":["Categorical data","Numerical data","Time series data","Audio data"],"ans":"Categorical data","why":"They place people into categories."},{"q":"Heights of students measured in centimetres are:","opts":["Numerical data","Categorical data","Text data","Image data"],"ans":"Numerical data","why":"Heights are numeric values."},{"q":"X-ray photographs are an example of:","opts":["Image data","Audio data","Text data","Time series data"],"ans":"Image data","why":"They are stored as images."},{"q":"Recorded speech or music is an example of:","opts":["Audio data","Text data","Spatial data","Numerical data only"],"ans":"Audio data","why":"Sound recordings are audio data."},{"q":"Customer reviews and emails are examples of:","opts":["Text data","Audio data","Image data","Spatial data"],"ans":"Text data","why":"They are written language."},{"q":"Based on the mode of collection, data can be grouped into:","opts":["Primary, secondary and tertiary data","Descriptive and inferential data","Numerical and categorical data","Audio and image data"],"ans":"Primary, secondary and tertiary data","why":"This is the lecture’s second classification."},{"q":"Primary data is data:","opts":["Collected directly from the source","Collected by someone else for another purpose","Summarised from other sources","Always found in books"],"ans":"Collected directly from the source","why":"Primary data is first-hand."},{"q":"Which of these is a method of collecting primary data?","opts":["Questionnaires","Journals","Government publications","White papers"],"ans":"Questionnaires","why":"Others: surveys, interviews, focus groups, observations."},{"q":"Secondary data is data:","opts":["Collected by someone else and used for a different purpose","Collected directly by the user","Distilled from reports only","Never published"],"ans":"Collected by someone else and used for a different purpose","why":"It is second-hand data."},{"q":"Which is a source of secondary data?","opts":["Government publications","Interviews you conduct","Your own observations","Your own focus group"],"ans":"Government publications","why":"Others: books, journals, online databases."},{"q":"Tertiary data is data that:","opts":["Has been distilled and summarised from primary and secondary sources","Is collected first-hand","Is always numerical","Is unprocessed"],"ans":"Has been distilled and summarised from primary and secondary sources","why":"Tertiary data is a summary of earlier data."},{"q":"Which of these is an example of tertiary data?","opts":["A market research report","An interview you conducted","Your own questionnaire","A direct observation"],"ans":"A market research report","why":"Others: statistical reports and white papers."},{"q":"____ is the data that is collected directly by the user.","opts":["Primary data","Tertiary data","Secondary data","Categorical data"],"ans":"Primary data","why":"This was the pop-up quiz in the lecture."},{"q":"A student gives questionnaires to 100 classmates. The data is:","opts":["Primary data","Secondary data","Tertiary data","Spatial data"],"ans":"Primary data","why":"She collected it herself."},{"q":"A researcher uses census figures published by a government agency. The data is:","opts":["Secondary data","Primary data","Tertiary data","Audio data"],"ans":"Secondary data","why":"Someone else collected it for another purpose."},{"q":"A report that summarises many published studies is an example of:","opts":["Tertiary data","Primary data","A questionnaire","An observation"],"ans":"Tertiary data","why":"It distils other sources."},{"q":"A sample is:","opts":["A subset of a population used for analysis","The whole population","A graph","A type of survey"],"ans":"A subset of a population used for analysis","why":"Inference uses a sample to say something about the population."},{"q":"A population is:","opts":["The entire group being studied","A small group chosen from a larger one","One observation","A formula"],"ans":"The entire group being studied","why":"The population is the full set of interest."},{"q":"‘87% of women compare their bodies to images on social media’ is, in the lecture’s terms, an example of:","opts":["statistics (lowercase)","Statistics (the field)","A tertiary data source","An inferential method"],"ans":"statistics (lowercase)","why":"It is a piece of numerical information."},{"q":"Which of these best describes ‘Statistics’, ‘statistics’ and ‘statistic’?","opts":["Field, numerical data, and a value calculated from data","All mean exactly the same","Branch, graph, and survey","Sample, population, and mean"],"ans":"Field, numerical data, and a value calculated from data","why":"This is the pop-up quiz distinction."},{"q":"Which branch of statistics relies on probability to generalise?","opts":["Inferential statistics","Descriptive statistics","Neither","Both equally"],"ans":"Inferential statistics","why":"The lecture says induction is achieved in a probabilistic framework."},{"q":"Which branch of statistics uses summaries such as averages and charts of the data at hand?","opts":["Descriptive statistics","Inferential statistics","Neither","Tertiary statistics"],"ans":"Descriptive statistics","why":"It summarises data in a meaningful way."},{"q":"Using statistics to estimate demand before launching a product supports:","opts":["Effective feasibility studies","Choosing a font","Avoiding data","Deleting data"],"ans":"Effective feasibility studies","why":"Feasibility studies are listed as an importance."},{"q":"Using statistics to predict next year’s sales supports:","opts":["Forecasting future activities and targets","Descriptive tables only","Eliminating risk","Collecting secondary data only"],"ans":"Forecasting future activities and targets","why":"Forecasting is a listed importance."}]},{"id":"sta2","code":"Statistics","title":"Basic Tools for Statistical Data Analysis","color":"#17766e","timePerQ":30,"questions":[{"q":"Tools for statistical data analysis are apparatuses used to:","opts":["Present data before analysis or present results after analysis","Replace data collection","Create data from nothing","Remove errors from all data"],"ans":"Present data before analysis or present results after analysis","why":"The tools support both data presentation and results presentation."},{"q":"Which of these are common tools used in statistical data analysis?","opts":["Texts, tables, graphs, charts and pictograms","Only formulas","Only calculators","Only surveys"],"ans":"Texts, tables, graphs, charts and pictograms","why":"These are the tools named in the lecture."},{"q":"Unprocessed data must often be organised before analysis because:","opts":["Raw data does not easily give meaning","Raw data is always wrong","Analysis is impossible with numbers","Graphs cannot use data"],"ans":"Raw data does not easily give meaning","why":"Organising and presenting data helps meaning emerge."},{"q":"Texts in statistics are used to:","opts":["Convey statistical information in written language","Draw histograms","Count frequencies automatically","Display points on axes"],"ans":"Convey statistical information in written language","why":"Texts report results and findings in words."},{"q":"‘Unemployment Rate in Nigeria averaged 12.84 percent from 2006 until 2020…’ is an example of presenting data using:","opts":["Text","A table","A pictogram","A histogram"],"ans":"Text","why":"It conveys statistical information in a written sentence."},{"q":"In statistics, a table presents data:","opts":["In rows and columns in a structured format","As slices of a circle","As pictures","Only in sentences"],"ans":"In rows and columns in a structured format","why":"A table is a structured grid."},{"q":"Tables are used to:","opts":["Summarise, organise and display large amounts of data","Show only one value","Replace all graphs","Hide data"],"ans":"Summarise, organise and display large amounts of data","why":"They make data easier to interpret and analyse."},{"q":"How many forms of tables are named in the lecture?","opts":["Four","Two","Three","Six"],"ans":"Four","why":"Simple, complex, frequency and contingency tables."},{"q":"Which is NOT a form of table named in the lecture?","opts":["Pictorial table","Simple table","Complex table","Contingency table"],"ans":"Pictorial table","why":"The four forms are simple, complex, frequency and contingency."},{"q":"A simple table summarises information on:","opts":["A single characteristic or variable","Two or more interrelated categories","Relationship between variables only","Pictures"],"ans":"A single characteristic or variable","why":"Simple tables handle one variable."},{"q":"A complex table presents information:","opts":["In two or more interrelated categories","About one variable only","As bars","As pictures"],"ans":"In two or more interrelated categories","why":"Complex tables summarise complex information."},{"q":"A frequency table summarises:","opts":["The number of times each value or category occurs","The relationship of two variables","Only quartiles","A pie slice"],"ans":"The number of times each value or category occurs","why":"It lists frequencies."},{"q":"A contingency table is used to:","opts":["Display frequencies of two or more variables and investigate their relationship","Count one variable","Show a single trend","Draw pictograms"],"ans":"Display frequencies of two or more variables and investigate their relationship","why":"Contingency tables cross-classify variables."},{"q":"Which table would you use to study the relationship between gender and course choice?","opts":["Contingency table","Simple table","Pictogram","Text"],"ans":"Contingency table","why":"It shows frequencies of two variables together."},{"q":"Which table would you use to count how many students got each grade?","opts":["Frequency table","Contingency table","Box plot","Pie chart"],"ans":"Frequency table","why":"It shows how often each grade occurs."},{"q":"A graph is also known as a:","opts":["Chart or plot","Table or text","Pictogram only","Formula"],"ans":"Chart or plot","why":"Graphs, charts and plots are visual representations of data."},{"q":"Graphs help to reveal:","opts":["Patterns, trends and relationships","Only exact numbers","Only errors","Nothing beyond tables"],"ans":"Patterns, trends and relationships","why":"They show features that numerical summaries may hide."},{"q":"Which of these is a commonly used graph in statistics?","opts":["Histogram","Contingency table","Text","Frequency table"],"ans":"Histogram","why":"Histograms, scatter plots, box plots, bar charts, line graphs and pie charts."},{"q":"A histogram displays:","opts":["The distribution of a continuous variable using bins","Categorical proportions as slices","A relationship using lines only","Pictures of counts"],"ans":"The distribution of a continuous variable using bins","why":"Data is divided into intervals (bins)."},{"q":"In a histogram, a ‘bin’ is:","opts":["An interval of values","A category label","A slice of a pie","A picture"],"ans":"An interval of values","why":"The variable is divided into intervals."},{"q":"A scatter plot displays:","opts":["The relationship between two continuous variables as points","Categories as slices","Frequencies as bars only","One variable only"],"ans":"The relationship between two continuous variables as points","why":"Each observation is plotted as a point."},{"q":"A box plot shows the:","opts":["Median, quartiles and outliers","Pie slices","Pictogram counts","Only the mean"],"ans":"Median, quartiles and outliers","why":"It displays distribution using key summary values."},{"q":"A bar chart displays:","opts":["Frequency or proportion of categorical data using bars","A continuous variable in bins","Points on axes","Images"],"ans":"Frequency or proportion of categorical data using bars","why":"Bar heights show categories."},{"q":"How many types of bar charts are named in the lecture?","opts":["Three","Two","Four","Five"],"ans":"Three","why":"Simple, multiple and component bar charts."},{"q":"The three types of bar charts are:","opts":["Simple, multiple and component","Simple, complex and frequency","Single, double and triple","Vertical, pie and line"],"ans":"Simple, multiple and component","why":"These are the lecture’s three types."},{"q":"A simple bar chart consists of:","opts":["A set of non-joining bars","Slices of a circle","Joined bars with no gaps","Points joined by lines"],"ans":"A set of non-joining bars","why":"Bars can be vertical or horizontal."},{"q":"A multiple bar chart is used to:","opts":["Display two or more variables belonging to the same category","Show one variable only","Show only a trend over time","Show proportions of a circle"],"ans":"Display two or more variables belonging to the same category","why":"It compares variables side by side."},{"q":"A component bar chart is also known as a:","opts":["Stacked chart","Scatter chart","Pictogram","Frequency table"],"ans":"Stacked chart","why":"It stacks features that sum to a total."},{"q":"A component bar chart is used when a category:","opts":["Has several features that add up to its total","Has only one value","Has no data","Is continuous"],"ans":"Has several features that add up to its total","why":"Each bar is split into parts."},{"q":"A line graph displays the relationship between two continuous variables by:","opts":["Connecting the points with a line","Using slices","Using pictures","Using text"],"ans":"Connecting the points with a line","why":"Lines join the plotted points."},{"q":"Which graph is best for showing a trend over months?","opts":["Line graph","Pie chart","Pictogram","Contingency table"],"ans":"Line graph","why":"Lines show change across time."},{"q":"A pie chart is a circular graph that displays:","opts":["Categorical data as slices proportional to each category","Two continuous variables","Medians and quartiles","Time trends only"],"ans":"Categorical data as slices proportional to each category","why":"Slice size shows proportion."},{"q":"The size of a pie chart slice corresponds to:","opts":["The proportion of data in that category","The number of bars","The median","The scatter"],"ans":"The proportion of data in that category","why":"Bigger share, bigger slice."},{"q":"Pictograms use:","opts":["Images where the number of images represents frequency","Bars only","Lines only","Slices only"],"ans":"Images where the number of images represents frequency","why":"Pictograms are one of the simplest ways to show data."},{"q":"Which of these is described as one of the simplest ways to represent data?","opts":["Pictograms","Box plots","Contingency tables","Histograms"],"ans":"Pictograms","why":"The lecture says pictograms are among the simplest."},{"q":"If each icon in a pictogram represents 10 students and there are 4 icons, the frequency is:","opts":["40 students","4 students","14 students","104 students"],"ans":"40 students","why":"4 × 10 = 40."},{"q":"Which graph is best for the distribution of exam scores (a continuous variable)?","opts":["Histogram","Pie chart","Pictogram","Simple bar chart"],"ans":"Histogram","why":"Histograms show distribution of continuous data."},{"q":"Which graph is best for showing the relationship between height and weight?","opts":["Scatter plot","Pie chart","Pictogram","Simple bar chart"],"ans":"Scatter plot","why":"Both are continuous variables."},{"q":"Which graph is best for spotting outliers?","opts":["Box plot","Pie chart","Pictogram","Frequency table"],"ans":"Box plot","why":"Box plots show outliers."},{"q":"Which chart is best for comparing monthly sales of three products side by side?","opts":["Multiple bar chart","Pie chart","Box plot","Simple text"],"ans":"Multiple bar chart","why":"It compares several variables in the same category."},{"q":"Which chart is best for showing total students per department split into male and female?","opts":["Component (stacked) bar chart","Scatter plot","Histogram","Line graph"],"ans":"Component (stacked) bar chart","why":"Each total is split into parts."},{"q":"Which chart is best for showing the share each region contributes to total sales?","opts":["Pie chart","Scatter plot","Box plot","Contingency table"],"ans":"Pie chart","why":"Slices show proportions of a whole."},{"q":"Which of these is NOT a type of bar chart?","opts":["Scattered bar chart","Simple bar chart","Multiple bar chart","Component bar chart"],"ans":"Scattered bar chart","why":"The three types are simple, multiple and component."},{"q":"Which pair is correctly matched?","opts":["Pie chart – categorical data","Histogram – categorical data","Scatter plot – one variable only","Box plot – text"],"ans":"Pie chart – categorical data","why":"Pie charts display categorical data as slices."},{"q":"A bar chart is for categorical data, while a histogram is for:","opts":["Continuous data","Text data","Audio data","Pictures only"],"ans":"Continuous data","why":"Histograms group continuous values into bins."},{"q":"Graphs are commonly used to:","opts":["Summarise and communicate results of data analysis clearly and concisely","Hide patterns","Replace data collection","Create errors"],"ans":"Summarise and communicate results of data analysis clearly and concisely","why":"They make results easy to see."},{"q":"Which tool would you use to say ‘In a class of 50 students, only 13 have a monthly allowance of #1000’?","opts":["Text","Scatter plot","Box plot","Histogram"],"ans":"Text","why":"It conveys information in written language."},{"q":"The lecture’s summary says the tools examined include:","opts":["Texts, tables, graphs and pictograms","Only graphs","Only tables","Only formulas"],"ans":"Texts, tables, graphs and pictograms","why":"These are the tools used for presenting data."},{"q":"A pop-up quiz asks for the various forms a table can take. Which list is correct?","opts":["Simple, complex, frequency and contingency","Simple, pictorial, bar and pie","Frequency, line, scatter and box","Text, graph, chart and pictogram"],"ans":"Simple, complex, frequency and contingency","why":"The lecture names four forms of table."},{"q":"Which two graphs both display the relationship between two continuous variables?","opts":["Scatter plot and line graph","Pie chart and bar chart","Histogram and pictogram","Box plot and frequency table"],"ans":"Scatter plot and line graph","why":"Scatter plots use points; line graphs connect the points with a line."}]},{"id":"hw","code":"Computer Science","title":"Introduction to Computer Hardware","color":"#5b4b9a","timePerQ":30,"questions":[{"q":"Computer hardware refers to:","opts":["The physical parts of a computer that we can see","The programs that run on a computer","The data stored on a disk","The instructions in the BIOS"],"ans":"The physical parts of a computer that we can see","why":"Hardware is the physical equipment."},{"q":"Which of these is NOT computer hardware?","opts":["An operating system","A keyboard","A monitor","A hard drive"],"ans":"An operating system","why":"The operating system is software."},{"q":"The main categories of computer hardware include:","opts":["Input, output, CPU, memory and storage devices","Only the keyboard and mouse","Only memory","Only the monitor"],"ans":"Input, output, CPU, memory and storage devices","why":"These are the lecture’s hardware groups."},{"q":"Which of these is an input device?","opts":["Keyboard","Monitor","Printer","Speaker"],"ans":"Keyboard","why":"A keyboard sends information into the computer."},{"q":"Which of these is an input device?","opts":["Mouse","Printer","Monitor","Speakers"],"ans":"Mouse","why":"A mouse sends commands into the computer."},{"q":"A stylus pen is an example of a(n):","opts":["Input device","Output device","Storage device","Memory chip"],"ans":"Input device","why":"Keyboard, stylus pen and mouse are input devices."},{"q":"Which of these is an input device?","opts":["Touchscreen","Printer","Monitor","Speakers"],"ans":"Touchscreen","why":"Touchscreens are listed among input devices."},{"q":"Input devices allow information to:","opts":["Flow into a computer system","Flow out of a computer system","Be stored permanently only","Be deleted"],"ans":"Flow into a computer system","why":"That is why they are called input devices."},{"q":"Output devices allow information to:","opts":["Flow out of a computer system","Flow into a computer system","Be typed","Be erased"],"ans":"Flow out of a computer system","why":"Printers, speakers and monitors present information."},{"q":"Which of these is an output device?","opts":["Printer","Keyboard","Mouse","Stylus pen"],"ans":"Printer","why":"A printer produces output."},{"q":"Which of these is an output device?","opts":["Speakers","Mouse","Keyboard","Stylus pen"],"ans":"Speakers","why":"Speakers output sound."},{"q":"Which of these is an output device?","opts":["Monitor","Mouse","Stylus pen","Keyboard"],"ans":"Monitor","why":"The monitor displays output."},{"q":"CPU stands for:","opts":["Central Processing Unit","Central Program Unit","Computer Power Unit","Control Processing Utility"],"ans":"Central Processing Unit","why":"The CPU is also called the processor."},{"q":"The first microprocessor was the:","opts":["Intel 4004","Intel Core i7","ENIAC","Pentium"],"ans":"Intel 4004","why":"The Intel 4004 appeared in 1971."},{"q":"The Intel 4004 was introduced in:","opts":["1971","1947","1943","1995"],"ans":"1971","why":"The lecture names 1971."},{"q":"According to the lecture, the Intel 4004 had how many transistors?","opts":["2,300","17,000","106,000","16,000,000"],"ans":"2,300","why":"The lecture states 2300 transistors."},{"q":"According to the lecture, the Intel 4004 operated at:","opts":["106 KHz","106 GHz","2300 KHz","16 MHz"],"ans":"106 KHz","why":"The lecture gives 106 KHz."},{"q":"The unit of processor measurement is the:","opts":["Hertz","Byte","Newton","Joule"],"ans":"Hertz","why":"Processor speed is measured in Hertz."},{"q":"A processor running at 106 KHz can, per the lecture, process:","opts":["106,000 instructions per second","106 instructions per second","1,060 instructions per second","106,000,000 instructions per second"],"ans":"106,000 instructions per second","why":"The lecture equates 106 KHz to 106,000 instructions per second."},{"q":"A typical instruction for a processor might be to:","opts":["Add two numbers","Print a poster","Charge a battery","Plug in a keyboard"],"ans":"Add two numbers","why":"The lecture’s example is 2 + 2."},{"q":"Instructions are sent to the processor by the:","opts":["Operating system","Printer","Power unit","Monitor"],"ans":"Operating system","why":"The operating system sends instructions to the CPU."},{"q":"When a processor decodes an instruction, it:","opts":["Understands the assignment at hand","Saves it permanently","Prints it","Deletes it"],"ans":"Understands the assignment at hand","why":"Decoding means understanding the task."},{"q":"After decoding, the instruction is:","opts":["Executed","Deleted","Copied to the printer","Typed"],"ans":"Executed","why":"The processor decodes and then executes."},{"q":"RAM stands for:","opts":["Random Access Memory","Read Access Memory","Rapid Application Memory","Random Application Module"],"ans":"Random Access Memory","why":"RAM is the computer’s temporary memory."},{"q":"RAM stores information:","opts":["Temporarily","Permanently","Only when the computer is off","Only on paper"],"ans":"Temporarily","why":"The processor stores information temporarily on RAM to access it quickly."},{"q":"The processor uses RAM so that it can:","opts":["Access information quickly","Print faster","Cool the system","Save files for years"],"ans":"Access information quickly","why":"RAM provides fast temporary storage."},{"q":"RAM allows the processor to:","opts":["Run multiple programs at once","Store files forever","Supply power","Connect to a printer"],"ans":"Run multiple programs at once","why":"More RAM supports multitasking."},{"q":"Generally, having more RAM leads to:","opts":["Better computer performance","Worse performance","No change","Louder fans"],"ans":"Better computer performance","why":"The lecture says the more RAM, the better the performance."},{"q":"Information on RAM might include:","opts":["The document you are currently working on","Your BIOS setup","Files stored for years","Printer ink levels"],"ans":"The document you are currently working on","why":"RAM holds current documents, images and music being used."},{"q":"RAM capacity is rated in:","opts":["Bytes","Hertz","Newtons","Pixels"],"ans":"Bytes","why":"16M byte RAM holds about 16,000,000 bytes."},{"q":"A 16 MB RAM, per the lecture, can hold about:","opts":["16,000,000 bytes","16,000 bytes","160,000 bytes","16 bytes"],"ans":"16,000,000 bytes","why":"M stands for mega (million)."},{"q":"Which kind of device stores information permanently?","opts":["Hard disk","RAM","Cache","Power unit"],"ans":"Hard disk","why":"Hard disks keep files after shutdown."},{"q":"When you shut down the computer, information on the hard disk:","opts":["Remains","Is lost","Moves to RAM","Is printed"],"ans":"Remains","why":"The hard disk stores information permanently."},{"q":"Two kinds of hard disk are:","opts":["HDD and SSD","RAM and ROM","CPU and GPU","LCD and LED"],"ans":"HDD and SSD","why":"Hard Disk Drives and Solid State Drives."},{"q":"HDD stands for:","opts":["Hard Disk Drive","High Data Device","Hard Data Disk","Heavy Disk Drive"],"ans":"Hard Disk Drive","why":"HDD is the traditional hard disk."},{"q":"SSD stands for:","opts":["Solid State Drive","Super Speed Disk","Solid Storage Device","Secure State Drive"],"ans":"Solid State Drive","why":"SSDs use integrated circuits."},{"q":"An HDD is susceptible to damage because it has:","opts":["A moveable head that reads and writes to the disk","No parts","Only integrated circuits","A built-in screen"],"ans":"A moveable head that reads and writes to the disk","why":"Moving parts can be damaged."},{"q":"An SSD differs from an HDD in that an SSD:","opts":["Has no moveable parts","Has a moveable head","Is always cheaper","Cannot store files"],"ans":"Has no moveable parts","why":"SSDs are made of integrated circuits."},{"q":"SSDs last longer than HDDs and as such are:","opts":["More expensive","Cheaper","Free","Larger"],"ans":"More expensive","why":"The lecture links longer life with higher price."},{"q":"Storage capacity is usually measured in:","opts":["Bytes","Hertz","Watts","Metres"],"ans":"Bytes","why":"50 MB is 50,000,000 bytes."},{"q":"A 50 MB storage device can store about:","opts":["50,000,000 bytes","50,000 bytes","500,000 bytes","50 bytes"],"ans":"50,000,000 bytes","why":"Mega means million (decimal convention)."},{"q":"Using the lecture’s decimal convention, 1 TB equals:","opts":["1,000,000,000,000 bytes","1,000,000 bytes","1,000,000,000 bytes","1,000 bytes"],"ans":"1,000,000,000,000 bytes","why":"Tera means 10¹²."},{"q":"ROM stands for:","opts":["Read Only Memory","Random Only Memory","Read Online Memory","Rapid Output Memory"],"ans":"Read Only Memory","why":"ROM stores configuration data."},{"q":"ROM stores:","opts":["Configuration data such as how the computer starts up","Your open documents","Your music while playing","Printer paper"],"ans":"Configuration data such as how the computer starts up","why":"It holds startup instructions."},{"q":"BIOS stands for:","opts":["Basic Input and Output System","Basic Internet Operating System","Binary Input Output Service","Base Input Output Software"],"ans":"Basic Input and Output System","why":"BIOS resides on the ROM."},{"q":"The BIOS resides on the:","opts":["ROM","Printer","Monitor","Mouse"],"ans":"ROM","why":"The BIOS is stored in read-only memory."},{"q":"The BIOS helps ensure that:","opts":["Hardware parts are working properly","Documents are printed","Passwords are shared","Games load"],"ans":"Hardware parts are working properly","why":"It checks hardware at startup."},{"q":"The power unit:","opts":["Supplies power to the components that need it","Stores files permanently","Decodes instructions","Prints documents"],"ans":"Supplies power to the components that need it","why":"It powers the fan unit, processor and memories."},{"q":"Which of these is a storage device?","opts":["Optical drive","Monitor","Keyboard","Speaker"],"ans":"Optical drive","why":"Hard drives, solid-state drives and optical drives are storage devices."},{"q":"Which three types of memory are listed in the lecture?","opts":["RAM, ROM and cache","RAM, HDD and SSD","ROM, BIOS and CPU","Cache, monitor and RAM"],"ans":"RAM, ROM and cache","why":"The lecture lists RAM, ROM and cache under memory."}]},{"id":"csc","code":"CSC101","title":"A Brief History of Computing and Its Impact on Society","color":"#9a6a00","timePerQ":30,"questions":[{"q":"Computing may be traced back to prehistoric times when humans used machines such as the:","opts":["Abacus","ENIAC","Microprocessor","Smartphone"],"ans":"Abacus","why":"The abacus was used for mathematical computation."},{"q":"The abacus is described in the lecture as a:","opts":["Mechanical computer","Vacuum tube computer","Personal computer","Integrated circuit"],"ans":"Mechanical computer","why":"The slide labels it a mechanical computer."},{"q":"The first computers did not appear until the:","opts":["1940s","1840s","1970s","1990s"],"ans":"1940s","why":"Vacuum tube computers date to the 1940s–1950s."},{"q":"ENIAC stands for:","opts":["Electronic Numerical Integrator and Calculator","Electronic Network Integrated Analog Computer","Electric Numerical Input and Calculator","Early Numerical Integrated Computer"],"ans":"Electronic Numerical Integrator and Calculator","why":"ENIAC was an early general-purpose electronic computer."},{"q":"ENIAC was notable as one of the first:","opts":["General-purpose electronic computers that could be reprogrammed","Smartphones","Laptops","Microprocessors"],"ans":"General-purpose electronic computers that could be reprogrammed","why":"It could be reprogrammed for different purposes."},{"q":"ENIAC was designed and built by Presper Eckert and colleagues at the:","opts":["University of Pennsylvania","Intel Corporation","University of Lagos","Microsoft"],"ans":"University of Pennsylvania","why":"It was built at the University of Pennsylvania."},{"q":"ENIAC was designed and built between:","opts":["1943 and 1945","1947 and 1950","1971 and 1975","1990 and 1995"],"ans":"1943 and 1945","why":"The lecture gives 1943–45."},{"q":"ENIAC housed about how many vacuum tubes?","opts":["17,000","2,300","106,000","1,000,000"],"ans":"17,000","why":"The lecture states about 17,000 vacuum tubes."},{"q":"Vacuum tube computers belong to which period?","opts":["1940s–1950s","1960s–1970s","1980s–1990s","2000s"],"ans":"1940s–1950s","why":"They were the first-generation computers."},{"q":"The transistor was developed in:","opts":["1947","1943","1971","1995"],"ans":"1947","why":"The transistor transformed computing technology."},{"q":"The transistor replaced:","opts":["Hefty vacuum tubes","Integrated circuits","Microprocessors","The abacus"],"ans":"Hefty vacuum tubes","why":"Transistors replaced bulky vacuum tubes."},{"q":"Transistors made computers more:","opts":["Compact, dependable and effective","Bulky and unreliable","Expensive only","Mechanical"],"ans":"Compact, dependable and effective","why":"They improved size, reliability and efficiency."},{"q":"The idea of integrated circuits arose in the:","opts":["Late 1950s and early 1960s","1840s","Early 1990s","2010s"],"ans":"Late 1950s and early 1960s","why":"Integrated circuits allowed miniaturisation."},{"q":"An integrated circuit places several transistors on:","opts":["A single silicon chip","A vacuum tube","A mechanical frame","A sheet of paper"],"ans":"A single silicon chip","why":"That enabled miniaturisation."},{"q":"Which period is linked with transistors and integrated circuits?","opts":["1950s–1970s","1940s–1950s","1990s–2000s","1800s"],"ans":"1950s–1970s","why":"The lecture labels this era 1950s–1970s."},{"q":"The first personal computers resulted from the:","opts":["Early 1970s microprocessor revolution","Invention of the abacus","ENIAC project only","Invention of vacuum tubes"],"ans":"Early 1970s microprocessor revolution","why":"The microprocessor led to PCs."},{"q":"Today, many computers can be found on:","opts":["Desktops, laptops and smartphones","Only mainframes","Only large rooms","Only universities"],"ans":"Desktops, laptops and smartphones","why":"Computers have become widely portable."},{"q":"Over time, the weight and energy consumption of computers have:","opts":["Reduced dramatically while processing speed has grown","Increased dramatically","Stayed the same","Reduced while speed also fell"],"ans":"Reduced dramatically while processing speed has grown","why":"The lecture notes smaller, more efficient and faster machines."},{"q":"Which is the correct chronological order?","opts":["Abacus → vacuum tubes → transistors → integrated circuits → personal computers","Personal computers → abacus → transistors → vacuum tubes","Transistors → abacus → vacuum tubes → personal computers","Vacuum tubes → personal computers → abacus → transistors"],"ans":"Abacus → vacuum tubes → transistors → integrated circuits → personal computers","why":"This follows the lecture’s timeline."},{"q":"Which came first?","opts":["The abacus","ENIAC","The transistor","The microprocessor"],"ans":"The abacus","why":"The abacus dates back to prehistoric times."},{"q":"The transistor (1947) was developed:","opts":["After ENIAC was completed (1945)","Before ENIAC was started (1943)","In the 1970s","In the 1990s"],"ans":"After ENIAC was completed (1945)","why":"ENIAC was built 1943–45; the transistor came in 1947."},{"q":"Connection to the internet made computers useful in sectors such as:","opts":["Education, entertainment, communication and health","Only entertainment","Only health","Only education"],"ans":"Education, entertainment, communication and health","why":"The lecture names these four sectors."},{"q":"How have computers enhanced education?","opts":["By giving access to information and improving literacy, especially in remote places","By removing the need for formal education","By banning books","By closing schools"],"ans":"By giving access to information and improving literacy, especially in remote places","why":"They complement formal education."},{"q":"Computers help literacy particularly in places where:","opts":["Educational institutions are not accessible","Schools are very close","There is no electricity at all","No one reads"],"ans":"Educational institutions are not accessible","why":"They provide access to information remotely."},{"q":"Computers are described as being a ____ to formal education.","opts":["Complement","Replacement","Barrier","Competitor"],"ans":"Complement","why":"They complement formal education."},{"q":"Which of these messaging platforms are named in the lecture?","opts":["WhatsApp, Yahoo Messenger, Twitter and Facebook","Only WhatsApp","Only email","Only SMS"],"ans":"WhatsApp, Yahoo Messenger, Twitter and Facebook","why":"They illustrate computer-enabled communication."},{"q":"During the Covid-19 pandemic, computers helped:","opts":["Bring people together despite the lockdown","Spread the virus","Close the internet","Replace doctors"],"ans":"Bring people together despite the lockdown","why":"They enabled communication under lockdown."},{"q":"In healthcare, computers make it possible to:","opts":["View digital images such as images of organs for objective diagnosis","Replace all doctors","Remove hospitals","Avoid diagnosis"],"ans":"View digital images such as images of organs for objective diagnosis","why":"Digital images support diagnosis."},{"q":"Computers help medical experts collaborate by:","opts":["Sending images to experts via computer","Printing all records","Closing clinics","Avoiding images"],"ans":"Sending images to experts via computer","why":"Images can be shared electronically."},{"q":"Computers enhance entertainment because they:","opts":["Can process instructions very fast, which suits games","Are slow","Cannot connect to others","Have no screens"],"ans":"Can process instructions very fast, which suits games","why":"Fast processing allows gaming."},{"q":"Computers allow people to play games:","opts":["With friends thousands of miles apart","Only alone","Only in the same room","Only on paper"],"ans":"With friends thousands of miles apart","why":"The internet connects players worldwide."},{"q":"Which of these is a downside of computing technologies named in the lecture?","opts":["Cyber-security threats","Faster communication","Digital diagnosis","Access to information"],"ans":"Cyber-security threats","why":"The lecture names cyber-security, cyberbullying and privacy concerns."},{"q":"Which three challenges are highlighted in the lecture?","opts":["Cyber-security, cyberbullying and privacy concerns","Speed, size and cost","Education, health and entertainment","Hardware, software and networking"],"ans":"Cyber-security, cyberbullying and privacy concerns","why":"These are the ethical implications."},{"q":"A cyber threat in the lecture includes:","opts":["Shutting computers down illegally","Learning online","Sharing a recipe","Watching a film"],"ans":"Shutting computers down illegally","why":"Illegal shutdowns are cyber threats."},{"q":"Cyberbullying can take the form of:","opts":["Instructing online users to do things against their will and sending threats","Sending a friendly greeting","Updating software","Playing games"],"ans":"Instructing online users to do things against their will and sending threats","why":"The lecture gives this example."},{"q":"A privacy concern in computing is:","opts":["Stealing private information such as credit card details","Using a keyboard","Charging a laptop","Printing a document"],"ans":"Stealing private information such as credit card details","why":"Stealing private data violates privacy."},{"q":"A recommended way to respond to cyberbullying is to:","opts":["Report to the police","Ignore it forever","Reply with threats","Share passwords"],"ans":"Report to the police","why":"The lecture suggests reporting to the police."},{"q":"A recommended way to reduce cyber threats is to:","opts":["Install security hardware and software on your network","Share your password","Turn off all updates","Use the same weak password"],"ans":"Install security hardware and software on your network","why":"Security tools help protect networks."},{"q":"Which of these is a good security habit mentioned in the lecture?","opts":["Do not share your password","Share your password with friends","Write your password in public","Disable security software"],"ans":"Do not share your password","why":"Passwords should be kept private."},{"q":"One learning objective of the lecture is to explain the:","opts":["Historical development of computing technologies","Rules of the English noun","Types of tables in statistics","Dimensions of physical quantities"],"ans":"Historical development of computing technologies","why":"This is the first objective."},{"q":"Another learning objective is to highlight the impact of computing technologies on:","opts":["Healthcare, education and entertainment","Only agriculture","Only mining","Only fashion"],"ans":"Healthcare, education and entertainment","why":"These sectors are named in the objectives."},{"q":"A third learning objective is to highlight the:","opts":["Downsides of computing technologies","Cost of the abacus","Names of all inventors","Colours of computers"],"ans":"Downsides of computing technologies","why":"The lecture considers the downsides as well as the benefits."},{"q":"Which technology is the earliest on the lecture’s timeline?","opts":["Abacus","Transistor","Microprocessor","Integrated circuit"],"ans":"Abacus","why":"It is traced to prehistoric times."},{"q":"Which technology put many transistors on a single silicon chip?","opts":["Integrated circuits","Vacuum tubes","The abacus","ENIAC"],"ans":"Integrated circuits","why":"That is the idea behind integrated circuits."},{"q":"Which technology sparked the early 1970s revolution that led to personal computers?","opts":["Microprocessor","Vacuum tube","Abacus","Punch card"],"ans":"Microprocessor","why":"The microprocessor made PCs possible."},{"q":"Which of these is a benefit rather than a downside of computers?","opts":["Access to information in remote places","Cyberbullying","Stolen credit card information","Illegal shutdowns"],"ans":"Access to information in remote places","why":"The others are downsides."},{"q":"Which of these is a downside rather than a benefit of computers?","opts":["Cyberbullying","Instant messaging","Digital diagnosis","Online gaming with friends"],"ans":"Cyberbullying","why":"Cyberbullying is an ethical concern."},{"q":"The lecture is mainly about:","opts":["The history of computing and its impact on society","Statistics tables","English grammar","Kinematics"],"ans":"The history of computing and its impact on society","why":"The title is ‘A Brief History of Computing and its Impact on Society’."},{"q":"The advent of modern computers also brought about their connection to the:","opts":["Internet","Abacus","Vacuum tube","Printer only"],"ans":"Internet","why":"The lecture says this connection made computers useful across sectors."},{"q":"Instant messaging applications such as WhatsApp and Twitter are made possible because:","opts":["Computers exist","Vacuum tubes exist","The abacus exists","Printers exist"],"ans":"Computers exist","why":"Communication via text and messaging relies on computers."}]}];
